"""Local source-watching dashboard and report. No public hosting or source downloads."""
from datetime import datetime,timezone
from html import escape
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
import argparse,json,runpy,threading,time,webbrowser
from pathlib import Path
from statistics import median
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.graphics.shapes import Drawing,Line,PolyLine,String

ROOT=Path(__file__).resolve().parent
INPUTS=[ROOT/'input'/'PHO_Chronic_Disease_Inc_Prev_Snapshot_2014_2023.xlsx',ROOT/'input'/'CIHI_Wait_Times_Priority_Procedures_2025.xlsx']
LOCK=threading.Lock();STATE={};STOP=threading.Event()
def signature():return tuple((p.stat().st_mtime_ns,p.stat().st_size) for p in INPUTS)
def fmt(value):return 'Not available' if value is None else f'{value:,.1f}'
def summarize(data):
    py=max(r['Year'] for r in data['pho']);wy=max(r['Year'] for r in data['provinceWait'])
    summary=[]
    for indicator in data['indicators']:
        if indicator['Statistic']!='Prevalence':continue
        rows=[r for r in data['pho'] if r['Indicator']==indicator['Indicator'] and r['Year']==py and r['Rate'] is not None]
        province=next((r['Rate'] for r in data['province'] if r['Indicator']==indicator['Indicator'] and r['Year']==py),None)
        summary.append([indicator['Disease'],fmt(province),fmt(median(r['Rate'] for r in rows)) if rows else 'Not available',str(len(rows))])
    procedure='Hip Replacement'
    wait=next((r for r in data['provinceWait'] if r['Procedure']==procedure and r['Year']==wy),{})
    regions=sorted([r for r in data['regionWait'] if r['Procedure']==procedure and r['Year']==wy],key=lambda r:r['MedianDays'] if r['MedianDays'] is not None else -1,reverse=True)
    return py,wy,summary,wait,regions
def make_pdf(data,stamp):
    py,wy,summary,wait,regions=summarize(data)
    styles=getSampleStyleSheet();styles['Title'].textColor=colors.HexColor('#29585F');styles['Title'].fontSize=23
    styles.add(ParagraphStyle('NoteSmall',parent=styles['BodyText'],fontSize=9,leading=13,textColor=colors.HexColor('#475A62')))
    def p(s,style='BodyText'):return Paragraph(escape(s),styles[style])
    story=[p('Ontario Chronic Disease & Healthcare Access','Title'),p('Mamkon Mercy Oyeleke | Automated historical-source report'),Spacer(1,9),p('Generated '+stamp,'NoteSmall'),Spacer(1,16),p('1. Chronic disease overview','Heading1'),p(f'Latest PHO year: {py}. Age-standardized prevalence rates, both sexes, per 100,000. The PHU median is unweighted; it is not a provincial population estimate.','NoteSmall'),Spacer(1,12)]
    def table(rows,colour,widths):
        t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor(colour)),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('LEADING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#DAE3E5')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F2F6F7')])]))
        return t
    story.append(table([['Disease','Ontario rate','Median PHU rate','PHUs']]+summary,'#693A77',[150,110,130,90]));story.append(Spacer(1,16))
    # Vector chart uses a single published provincial indicator, not an average of diseases.
    rows=sorted([r for r in data['province'] if r['Indicator']=='Prevalence of asthma' and r['Rate'] is not None],key=lambda r:r['Year'])
    if len(rows)>1:
        story.append(p('Ontario asthma prevalence trend','Heading2'));d=Drawing(470,180);left,bottom,width,height=55,30,385,125;lo=min(r['Rate'] for r in rows)*.98;hi=max(r['Rate'] for r in rows)*1.02
        points=[]
        for r in rows:points.extend([left+(r['Year']-rows[0]['Year'])/(rows[-1]['Year']-rows[0]['Year'])*width,bottom+(r['Rate']-lo)/(hi-lo)*height])
        for i in range(4):
            y=bottom+i*height/3;d.add(Line(left,y,left+width,y,strokeColor=colors.HexColor('#E3E8EC')));d.add(String(0,y-2,f'{lo+i*(hi-lo)/3:,.0f}',fontSize=8))
        d.add(PolyLine(points,strokeColor=colors.HexColor('#693A77'),strokeWidth=2));d.add(String(left,10,str(rows[0]['Year']),fontSize=8));d.add(String(left+width-20,10,str(rows[-1]['Year']),fontSize=8));story.append(d)
    story.extend([p('Source: supplied PHO workbook. Rates and missing/suppressed values are preserved. No new prediction or causal conclusion is generated by this report.','NoteSmall'),PageBreak(),p('2. Healthcare access','Heading1'),p(f'CIHI {wy} | Hip replacement | April-September reporting period. Median and 90th percentile are distinct statistics; regional medians are not averaged to reconstruct provincial values.','NoteSmall'),Spacer(1,12)])
    story.append(table([['Ontario median days','90th percentile days','Within benchmark'],[fmt(wait.get('MedianDays')),fmt(wait.get('P90Days')),fmt(wait.get('BenchmarkPct'))+'%' if wait.get('BenchmarkPct') is not None else 'Not available']],'#29585F',[160,160,160]));story.append(Spacer(1,18))
    story.append(table([['Health region','Median days','P90 days','Benchmark']]+[[r['Region'],fmt(r['MedianDays']),fmt(r['P90Days']),fmt(r['BenchmarkPct'])+'%' if r['BenchmarkPct'] is not None else 'Not available'] for r in regions],'#29585F',[180,100,100,100]))
    story.extend([Spacer(1,18),p('Methods and refresh','Heading2'),p('The local dashboard checks source files every 60 seconds while the server is running. A report is regenerated only after a successful source reload. PHO and CIHI geographies remain separate; no automatic geographic join or cross-source correlation is produced. CIHI fiscal-year and October-March records remain in the source extract but are excluded from comparable report facts.','NoteSmall'),Spacer(1,10),p('Colours: PHO purple #693A77 and blue #0F80A7; CIHI teal #00A199, dark teal #29585F and orange #ED7024, observed in publisher website materials. This is independent portfolio research, not an official publisher report.','NoteSmall'),Spacer(1,10),p('Sources: PHO_Chronic_Disease_Inc_Prev_Snapshot_2014_2023.xlsx; CIHI_Wait_Times_Priority_Procedures_2025.xlsx. These are historical releases; a new report timestamp does not mean a new publisher release.','NoteSmall')])
    tmp=ROOT/'report-building.pdf';SimpleDocTemplate(str(tmp),pagesize=(612,792),rightMargin=60,leftMargin=60,topMargin=40,bottomMargin=40,title='Ontario Analytics - Historical Source Report',author='Mamkon Mercy Oyeleke').build(story);tmp.replace(ROOT/'Automated-Report.pdf')
def make_report(data,stamp):
    py,wy,summary,wait,regions=summarize(data)
    def tab(headers,rows):return '<table><tr>'+''.join('<th>'+escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</table>'
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ontario Analytics Report</title><style>body{font:15px/1.6 Arial,sans-serif;color:#29585f;margin:35px auto;padding:20px;max-width:1000px}h1{color:#693a77}table{width:100%;border-collapse:collapse;font-size:13px;margin:20px 0}th{background:#29585f;color:white}td,th{text-align:left;padding:10px;border-bottom:1px solid #d9e3e5}a{color:#693a77}.note{font-size:12px;color:#53696e}@media print{.actions{display:none}body{margin:0}}</style><div class="actions"><a href="Dashboard-Preview.html">Dashboard</a> · <a href="Automated-Report.pdf">Download refreshed PDF report</a> · <button onclick="print()">Print report</button></div><h1>Ontario Analytics · Automated Report</h1><p>Mamkon Mercy Oyeleke</p><p class="note">Generated '+escape(stamp)+' · historical workbook data</p><h2>PHO prevalence overview · '+str(py)+'</h2><p>Age-standardized rates per 100,000, both sexes. The PHU median is unweighted.</p>'+tab(['Disease','Ontario rate','Median PHU rate','PHUs'],summary)+'<h2>CIHI hip replacement · '+str(wy)+'</h2><p>April–September reporting period only. Ontario median: '+fmt(wait.get('MedianDays'))+' days; 90th percentile: '+fmt(wait.get('P90Days'))+' days.</p>'+tab(['Region','Median days','90th percentile days','Within benchmark'],[[r['Region'],fmt(r['MedianDays']),fmt(r['P90Days']),fmt(r['BenchmarkPct'])+'%' if r['BenchmarkPct'] is not None else 'Not available'] for r in regions])+'<p class="note">No PHU/CIHI geographic join, new forecasts or causal conclusions. Source workbook definitions and missing values are preserved. This independent project uses colours observed in official publisher materials; no publisher endorsement is implied.</p></html>'
def refresh(force=False):
    with LOCK:
        try:
            sig=signature()
            if force or sig!=STATE.get('signature'):
                result=runpy.run_path(str(ROOT/'refresh_data.py'))
                if signature()!=sig:raise RuntimeError('Source files changed during refresh; try again after saving completes')
                data=result['preview'];stamp=datetime.now(timezone.utc).isoformat()
                make_pdf(data,stamp)
                report=make_report(data,stamp);(ROOT/'Automated-Report.html').write_text(report,encoding='utf-8')
                STATE.update(signature=sig,data=data,refreshed_at=stamp,report=report)
            STATE.pop('error',None)
        except Exception as error:
            STATE['error']='Source refresh failed: '+str(error)
        return dict(STATE)
def watcher():
    while not STOP.wait(60):refresh()
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path=self.path.split('?')[0]
        path={'/Dashboard-Preview.html':'/','/Automated-Report.pdf':'/report.pdf','/Automated-Report.html':'/report'}.get(path,path)
        if path not in ['/','/dashboard-data.json','/report','/report.pdf','/health']:
            self.reply(404,b'Not found','text/plain');return
        state=refresh()
        if state.get('error'):
            self.reply(503,json.dumps({'error':state['error'],'last_successful_refresh':state.get('refreshed_at')}).encode(),'application/json');return
        if path=='/':body=(ROOT/'dashboard-template.html').read_text(encoding='utf-8').replace('__DATA__',json.dumps(state['data'],ensure_ascii=False));self.reply(200,body.encode(),'text/html; charset=utf-8')
        elif path=='/dashboard-data.json':self.reply(200,json.dumps({'data':state['data'],'refreshed_at':state['refreshed_at']},ensure_ascii=False).encode(),'application/json; charset=utf-8')
        elif path=='/report':self.reply(200,state['report'].encode(),'text/html; charset=utf-8')
        elif path=='/report.pdf':self.reply(200,(ROOT/'Automated-Report.pdf').read_bytes(),'application/pdf')
        else:self.reply(200,json.dumps({'status':'ok','refreshed_at':state['refreshed_at'],'watch_seconds':60}).encode(),'application/json')
    def reply(self,status,body,kind):
        self.send_response(status);self.send_header('Content-Type',kind);self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff');self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--port',type=int,default=8770);parser.add_argument('--no-browser',action='store_true');args=parser.parse_args()
    state=refresh(True)
    if state.get('error'):raise SystemExit(state['error'])
    threading.Thread(target=watcher,daemon=True).start()
    server=ThreadingHTTPServer(('127.0.0.1',args.port),Handler)
    print(f'Automated dashboard: http://127.0.0.1:{args.port}/ | source check: 60 seconds',flush=True)
    if not args.no_browser:webbrowser.open(f'http://127.0.0.1:{args.port}/')
    try:server.serve_forever()
    except KeyboardInterrupt:pass
    finally:STOP.set();server.server_close()

